def _brute(g, h, p):
    cur = 1 % p
    for x in range(p):
        if cur == h % p:
            return x
        cur = cur * g % p
    return 1 if (g % p == 0 and h % p == 0) else None
for p in (2, 3, 5, 7, 11, 13, 29, 101):
    for g in range(p):
        for h in range(p):
            assert logaritma_diskrit(g, h, p) == _brute(g, h, p), (g, h, p)
rng = random.Random(23)
